public class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Normalize currency codes
        String normalizedBase = normalizeCurrencyCode(baseCurrency);
        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            normalizedQuotes.add(normalizeCurrencyCode(quote));
        }

        // Validate normalized codes
        if (!isValidCurrencyCode(normalizedBase)) {
            throw new ExchangeRateException('Invalid base currency code');
        }
        for (String quote : normalizedQuotes) {
            if (!isValidCurrencyCode(quote)) {
                throw new ExchangeRateException('Invalid quote currency code');
            }
        }

        // If quote set is null or empty after normalization, throw exception
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies set is null or empty');
        }

        // Build the symbols parameter (comma-separated, in any order)
        String symbols = String.join(new List<String>(normalizedQuotes), ',');

        // Make the HTTP callout
        HttpResponse response = makeCallout('GET', 'callout:FB_Exchange_Rates/v1/latest', 'base=' + normalizedBase + '&symbols=' + symbols);

        // Check response status
        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException('API request failed with status code: ' + response.getStatusCode());
        }

        // Parse JSON response
        Map<String, Object> jsonResponse = (Map<String, Object>) JSON.deserializeUntyped(response.getBody());
        if (!jsonResponse.containsKey('rates')) {
            throw new ExchangeRateException('Response missing rates object');
        }

        Map<String, Object> ratesMap = (Map<String, Object>) jsonResponse.get('rates');
        Map<String, Decimal> result = new Map<String, Decimal>();

        // For each requested currency, get the rate
        for (String quote : normalizedQuotes) {
            if (!ratesMap.containsKey(quote)) {
                throw new ExchangeRateException('Rate not found for currency: ' + quote);
            }
            Object rateObj = ratesMap.get(quote);
            if (!(rateObj instanceof Decimal)) {
                throw new ExchangeRateException('Rate value is not a decimal for currency: ' + quote);
            }
            result.put(quote, (Decimal) rateObj);
        }

        return result;
    }

    private static String normalizeCurrencyCode(String currencyCode) {
        if (currencyCode == null) {
            return '';
        }
        return currencyCode.trim().toUpperCase();
    }

    private static Boolean isValidCurrencyCode(String code) {
        if (code == null || code.length() != 3) {
            return false;
        }
        for (Integer i = 0; i < 3; i++) {
            Character c = code.charAt(i);
            if (c < 'A' || c > 'Z') {
                return false;
            }
        }
        return true;
    }

    private static HttpResponse makeCallout(String method, String endpoint, String queryParams) {
        Http http = new Http();
        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint + '?' + queryParams);
        request.setMethod(method);
        request.setHeader('Accept', 'application/json');

        // First attempt
        HttpResponse response = http.send(request);

        // Retry if status is 503
        if (response.getStatusCode() == 503) {
            response = http.send(request);
        }

        return response;
    }
}
