public class OpportunityPipelineHandler {
    private static boolean isProcessing = false;

    public static void handleTrigger(List<Opportunity> newOpps, Map<Id, Opportunity> oldOpps, boolean isInsert, boolean isUpdate, boolean isDelete, boolean isUndelete) {
        if (isProcessing) {
            return;
        }
        isProcessing = true;

        // Collect all account IDs affected by the opportunity DML
        Set<Id> accountIds = new Set<Id>();

        if (isInsert) {
            for (Opportunity opp : newOpps) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        } else if (isUpdate) {
            for (Opportunity newOpp : newOpps) {
                Opportunity oldOpp = oldOpps.get(newOpp.Id);
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        } else if (isDelete) {
            for (Opportunity oldOpp : oldOpps.values()) {
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        } else if (isUndelete) {
            for (Opportunity newOpp : newOpps) {
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
            }
        }

        // If no accounts are affected, we can skip
        if (accountIds.isEmpty()) {
            isProcessing = false;
            return;
        }

        // Query all open opportunities for these accounts
        List<Opportunity> openOpps = [
            SELECT Id, AccountId, Amount, IsClosed
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
        ];

        // Calculate the sum and count for each account
        Map<Id, Decimal> accountSumMap = new Map<Id, Decimal>();
        Map<Id, Integer> accountCountMap = new Map<Id, Integer>();

        for (Opportunity opp : openOpps) {
            Id accId = opp.AccountId;
            Decimal amount = opp.Amount != null ? opp.Amount : 0;
            accountSumMap.put(accId, accountSumMap.get(accId) == null ? amount : accountSumMap.get(accId) + amount);
            accountCountMap.put(accId, accountCountMap.get(accId) == null ? 1 : accountCountMap.get(accId) + 1);
        }

        // Prepare account updates
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Account acc = new Account(Id = accId);
            acc.FB_Open_Pipeline__c = accountSumMap.get(accId) != null ? accountSumMap.get(accId) : 0;
            acc.FB_Open_Opportunities__c = accountCountMap.get(accId) != null ? accountCountMap.get(accId) : 0;
            accountsToUpdate.add(acc);
        }

        // Update accounts
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }

        isProcessing = false;
    }
}
