public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
        // No-argument constructor
    }

    public void execute(SchedulableContext sc) {
        // Calculate the date thresholds
        DateTime now = System.now();
        DateTime thirtyDaysAgo = now.addDays(-30);
        DateTime oneEightyDaysAgo = now.addDays(-180);

        // Query logs to delete:
        // - Non-ERROR logs (including null Level__c) older than 30 days
        // - ERROR logs older than 180 days
        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (
                (Level__c != 'ERROR' OR Level__c IS NULL) 
                AND CreatedDate < :thirtyDaysAgo
            ) 
            OR (
                Level__c = 'ERROR' 
                AND CreatedDate < :oneEightyDaysAgo
            )
        ];

        // Delete the records if any exist
        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }

    public static Id scheduleNightly() {
        // Schedule to run daily at 02:00 (2:00 AM)
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
