public class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        // Return empty map if input is null or empty
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Get current calendar year boundaries
        Date today = Date.today();
        Date startOfYear = Date.newInstance(today.year(), 1, 1);
        Date endOfYear = Date.newInstance(today.year(), 12, 31);

        // Aggregate query to sum won opportunity amounts for current year
        List<AggregateResult> aggResults = [
            SELECT AccountId, SUM(Amount) AS totalAmount
            FROM Opportunity
            WHERE IsWon = true
                AND CloseDate >= :startOfYear
                AND CloseDate <= :endOfYear
                AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        // Build result map with all requested account IDs
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accId : accountIds) {
            result.put(accId, 0.0);
        }

        // Populate sums from aggregate results
        for (AggregateResult agg : aggResults) {
            Id accId = (Id) agg.get('AccountId');
            Decimal sum = (Decimal) agg.get('totalAmount');
            // If sum is null (no opportunities), keep 0; otherwise use the sum
            if (sum != null) {
                result.put(accId, sum);
            }
        }

        return result;
    }
}
