        // Test with discountPercentage = null
        try {
            OpportunitiesService.applyDiscounts(new Set<Id>(), null);
            System.assert(false, 'Expected OpportunitiesServiceException for null discountPercentage');
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            // Expected
        }

        // Test with discountPercentage = 0
        try {
            OpportunitiesService.applyDiscounts(new Set<Id>(), 0);
            System.assert(false, 'Expected OpportunitiesServiceException for discountPercentage 0');
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            // Expected
        }

        // Test with discountPercentage = 51
        try {
            OpportunitiesService.applyDiscounts(new Set<Id>(), 51);
            System.assert(false, 'Expected OpportunitiesServiceException for discountPercentage 51');
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            // Expected
        }

        // Verify that no mocks were used in these cases
