        OpportunitiesService.applyDiscounts(null, 10);
        mocks.verifyMockNotCalled(Application.Selector);
        mocks.verifyMockNotCalled(Application.Domain);
        mocks.verifyMockNotCalled(Application.UnitOfWork);

        // Test with empty ids
        OpportunitiesService.applyDiscounts(new Set<Id>(), 10);
