    @isTest
    private static void testApplyDiscounts_ValidInput_CallsCorrectMethods() {
        // Generate fake ids
        Set<Id> opportunityIds = new Set<Id>();
        opportunityIds.add(fflib_IDGenerator.generateId(Opportunity.SObjectType));
        opportunityIds.add(fflib_IDGenerator.generateId(Opportunity.SObjectType));

        // Create fake opportunities
        List<Opportunity> fakeOpps = createFakeOpportunities(opportunityIds);

        // Mock the selector
        IOpportunitiesSelector mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(mockSelector);
        mocks.expect(mockSelector.selectById(opportunityIds)).thenReturn(fakeOpps);

        // Mock the domain
        IOpportunities mockOpportunitiesDomain = (IOpportunities) mocks.mock(IOpportunities.class);
        Application.Domain.setMock(mockOpportunitiesDomain);
        // When Opportunities.newInstance is called, it uses Application.Domain.newInstance
        // We need to mock the domain factory to return our mock domain
        // Actually, Application.Domain.setMock sets the mock for the domain factory, so when
        // Application.Domain.newInstance is called, it returns our mock.
        // But we also need to ensure that the mock domain's applyDiscount is called correctly.

        // Mock the unit of work
        fflib_ISObjectUnitOfWork mockUnitOfWork = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(mockUnitOfWork);

        // Call the method
        OpportunitiesService.applyDiscounts(opportunityIds, 25);

        // Verify selector was called with correct ids
        mocks.verify(mockSelector).selectById(opportunityIds);

        // Verify domain's applyDiscount was called with correct parameters
        mocks.verify(mockOpportunitiesDomain).applyDiscount(25, mockUnitOfWork);

        // Verify unit of work's commitWork was called once
        mocks.verify(mockUnitOfWork).commitWork();
    }

    @isTest
    private static void testApplyDiscounts_DomainApplyDiscountNotCalledIfException() {
        // Test that when discountPercentage is invalid, the domain is not used
        try {
            OpportunitiesService.applyDiscounts(new Set<Id>(), -5);
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            // Expected
        }

        // Verify that the domain mock was not called
        mocks.verifyMockNotCalled(Application.Domain);
    }
}
