public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct() {
            return new Opportunities();
        }
    }

    @Override
    public void validate(List<SObject> records) {
        // Rule 1: Amount cannot be negative on insert and update
        for (SObject record : records) {
            Opportunity opp = (Opportunity) record;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }
        }

        // Rule 2: Amount cannot change on a won opportunity (if stage was already Closed Won before update)
        // Only applies to update records where we have old values
        if (isUpdate()) {
            Map<Id, SObject> oldMap = getOldMap();
            for (SObject record : records) {
                Opportunity opp = (Opportunity) record;
                Id oppId = opp.Id;
                if (oldMap.containsKey(oppId)) {
                    Opportunity oldOpp = (Opportunity) oldMap.get(oppId);
                    if (oldOpp.StageName == 'Closed Won') {
                        // Check if Amount changed
                        if (opp.Amount != oldOpp.Amount) {
                            error('Amount cannot change on a won opportunity.', opp, 'Amount');
                        }
                    }
                }
            }
        }
    }
}
