    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        fflib_SOQLQueryFactory queryFactory = getQueryFactory();
        // Add parent account Name field via relation
        queryFactory.addRelationField('Account.Name');
        // Filter for open opportunities and given accounts
        queryFactory.addWhereClause('IsClosed = :false');
        queryFactory.addWhereClause('AccountId IN :accountIds');
        // Order by Amount DESC (nulls last) then CloseDate ASC
        queryFactory.addOrderBy('Amount DESC, CloseDate ASC');
