public class CaseEscalationService {
    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        // If reason is blank, throw exception
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason cannot be blank');
        }

        // If caseIds is null or empty, do nothing
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Load cases using the selector
        ICasesSelector selector = CasesSelector.newInstance();
        List<Case> cases = selector.selectById(caseIds);

        // Prepare lists for changes and new tasks
        List<Case> casesToEscalate = new List<Case>();
        List<Task> tasksToCreate = new List<Task>();

        // Filter cases: skip Closed status and already escalated
        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }
            casesToEscalate.add(c);
        }

        // If no cases need escalating, return without commitWork
        if (casesToEscalate.isEmpty()) {
            return;
        }

        // Create unit of work
        fflib_IUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        // For each case to escalate, set fields and create a task
        Date tomorrow = Date.today().addDays(1);
        for (Case c : casesToEscalate) {
            c.IsEscalated = true;
            c.Priority = 'High';
            unitOfWork.registerDirty(c);

            Task t = new Task();
            t.Subject = 'Escalated: ' + reason;
            t.WhatId = c.Id;
            t.OwnerId = c.OwnerId;
            t.ActivityDate = tomorrow;
            t.Priority = 'High';
            tasksToCreate.add(t);
            unitOfWork.registerNew(t);
        }

        // Commit all work
        unitOfWork.commitWork();
    }
}
