public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        // Query contacts to get their phone numbers
        List<Contact> contacts = [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds];

        // List to hold contacts that need updating (those with a phone)
        List<Contact> contactsToUpdate = new List<Contact>();

        // Clean phone numbers for each contact that has one
        for (Contact contact : contacts) {
            if (contact.Phone != null && contact.Phone != '') {
                // Remove all characters that are not digits or '+'
                String cleanedPhone = contact.Phone.replaceAll('[^0-9+]', '');
                contact.Phone = cleanedPhone;
                contactsToUpdate.add(contact);
            }
        }

        // Perform bulk update with partial success allowed
        Database.SaveResult[] saveResults = Database.update(contactsToUpdate, false);

        // Build error map for contacts that failed to save
        Map<Id, String> errorMap = new Map<Id, String>();
        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];
            if (!result.isSuccess()) {
                // Get the first error message
                String firstError = result.getErrors()[0].getMessage();
                errorMap.put(contactsToUpdate[i].Id, firstError);
            }
        }

        return errorMap;
    }
}
