public class PipelineSummary {
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        // The four stages we need to sum
        List<String> stages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String stage : stages) {
            // Aggregate query for each stage
            AggregateResult ar = [
                SELECT SUM(Amount) total
                FROM Opportunity
                WHERE StageName = :stage
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            ];

            Decimal sum = (Decimal) ar.get('total');
            // If no opportunities, sum is null; we set to 0
            if (sum == null) {
                sum = 0;
            }
            result.put(stage, sum);
        }

        return result;
    }
}
