public class AccountRatingService {
    @future
    public static void recalculate(Set<Id> accountIds) {
        // Query all accounts that need recalculation
        List<Account> accounts = [SELECT Id, Rating FROM Account WHERE Id IN :accountIds];

        // Query all open opportunities for these accounts
        // Open = not Closed Won or Closed Lost
        List<Opportunity> opportunities = [
            SELECT Id, AccountId, StageName, Amount 
            FROM Opportunity 
            WHERE AccountId IN :accountIds 
            AND StageName NOT IN ('Closed Won', 'Closed Lost')
        ];

        // Group opportunities by account
        Map<Id, List<Opportunity>> opportunitiesByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity opp : opportunities) {
            if (!opportunitiesByAccount.containsKey(opp.AccountId)) {
                opportunitiesByAccount.put(opp.AccountId, new List<Opportunity>());
            }
            opportunitiesByAccount.get(opp.AccountId).add(opp);
        }

        // Update account ratings
        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : accounts) {
            List<Opportunity> accOpportunities = opportunitiesByAccount.get(acc.Id);

            if (accOpportunities == null || accOpportunities.isEmpty()) {
                acc.Rating = 'Cold';
            } else {
                Boolean hasBigOpportunity = false;
                for (Opportunity opp : accOpportunities) {
                    if (opp.Amount >= 100000) {
                        hasBigOpportunity = true;
                        break;
                    }
                }

                if (hasBigOpportunity) {
                    acc.Rating = 'Hot';
                } else {
                    acc.Rating = 'Warm';
                }
            }
            accountsToUpdate.add(acc);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
