import { LightningElement, track } from 'lwc';
import searchContacts from './contactController';

export default class ContactSearch extends LightningElement {
    @track searchTerm = '';
    @track contacts = [];
    @track error = null;

    private searchTimer;
    private requestId = 0;

    handleInputChange(event) {
        const trimmedValue = event.target.value.trim();

        // Clear any pending timer
        if (this.searchTimer) {
            clearTimeout(this.searchTimer);
            this.searchTimer = null;
        }

        // If trimmed value has fewer than 2 characters, clear results and do not search
        if (trimmedValue.length < 2) {
            this.contacts = [];
            this.error = null;
            return;
        }

        // Debounce: wait 300ms after user stops typing
        this.searchTimer = setTimeout(() => {
            // Increment requestId to track the latest request
            this.requestId++;
            const currentRequestId = this.requestId;

            // Call Apex method imperatively
            searchContacts({ searchTerm: trimmedValue })
                .then((result) => {
                    // Only update if this is the most recent request
                    if (currentRequestId === this.requestId) {
                        this.contacts = result;
                        this.error = null;
                    }
                })
                .catch((err) => {
                    // Only update error if this is the most recent request
                    if (currentRequestId === this.requestId) {
                        this.error = err.body?.message || 'An error occurred';
                        this.contacts = [];
                    }
                });
        }, 300);
    }

    // Clean up timer when component is disconnected
    disconnectedCallback() {
        if (this.searchTimer) {
            clearTimeout(this.searchTimer);
            this.searchTimer = null;
        }
    }
}
