import { LightningElement, track } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class EventRegistrationForm extends LightningElement {
    @track fullName = '';
    @track email = '';
    @track company = '';

    handleFullNameChange(event) {
        this.fullName = event.detail.value;
    }

    handleEmailChange(event) {
        this.email = event.detail.value;
    }

    handleCompanyChange(event) {
        this.company = event.detail.value;
    }

    handleRegister() {
        // Step 1: Validate email domain
        const emailInput = this.template.querySelector('[data-field="email"]');
        const emailDomain = this.email.split('@')[1]?.toLowerCase();
        const prohibitedDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

        if (prohibitedDomains.includes(emailDomain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: Report validity on all inputs
        const fullNameInput = this.template.querySelector('[data-field="fullName"]');
        const companyInput = this.template.querySelector('[data-field="company"]');

        fullNameInput.reportValidity();
        emailInput.reportValidity();
        companyInput.reportValidity();

        // Step 3: Check if any input is invalid
        if (!fullNameInput.validity.valid || !emailInput.validity.valid || !companyInput.validity.valid) {
            return;
        }

        // Step 4: Call Apex method imperatively
        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(result => {
                // Success: dispatch toast event
                const toastEvent = new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                });
                this.dispatchEvent(toastEvent);
            })
            .catch(error => {
                // Failure: dispatch toast event with error message
                const toastEvent = new ShowToastEvent({
                    title: 'Registration failed',
                    variant: 'error',
                    message: error.body.message
                });
                this.dispatchEvent(toastEvent);
            });
    }
}
