public class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // If map is null or empty, do nothing
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Get all contact IDs from the map
        Set<Id> contactIds = employerByContactId.keySet();

        // Query existing contacts to get their current primary affiliation
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ];

        // Query existing primary affiliations for these contacts
        List<npe5__Affiliation__c> existingPrimaryAffiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
                AND npe5__Primary__c = true
        ];

        // Create a map for quick lookup of existing primary affiliations by contact ID
        Map<Id, npe5__Affiliation__c> primaryAffiliationByContactId = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : existingPrimaryAffiliations) {
            primaryAffiliationByContactId.put(aff.npe5__Contact__c, aff);
        }

        // Lists to hold records to update/insert
        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        // Process each contact
        for (Contact contact : contacts) {
            Id contactId = contact.Id;
            Id newOrgId = employerByContactId.get(contactId);

            // If the new organization is already the primary affiliation, skip
            if (contact.npsp__Primary_Affiliation__c == newOrgId) {
                continue;
            }

            // If there's an existing primary affiliation, update it to Former
            npe5__Affiliation__c existingPrimaryAff = primaryAffiliationByContactId.get(contactId);
            if (existingPrimaryAff != null) {
                existingPrimaryAff.npe5__Status__c = 'Former';
                existingPrimaryAff.npe5__Primary__c = false;
                existingPrimaryAff.npe5__EndDate__c = Date.today();
                affiliationsToUpdate.add(existingPrimaryAff);
            }

            // Create new Current, primary affiliation
            npe5__Affiliation__c newAffiliation = new npe5__Affiliation__c();
            newAffiliation.npe5__Contact__c = contactId;
            newAffiliation.npe5__Organization__c = newOrgId;
            newAffiliation.npe5__Status__c = 'Current';
            newAffiliation.npe5__Primary__c = true;
            newAffiliation.npe5__StartDate__c = Date.today();
            affiliationsToInsert.add(newAffiliation);

            // Update contact's primary affiliation lookup
            contact.npsp__Primary_Affiliation__c = newOrgId;
            contactsToUpdate.add(contact);
        }

        // Perform DML operations
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
