public class RecurringGiftService {
    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        // Return empty list for null or empty input
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate all requests before any DML
        for (GiftRequest request : requests) {
            if (request.contactId == null) {
                throw new RecurringGiftException('Contact ID cannot be null');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException('Amount must be positive');
            }
            if (request.dayOfMonth < 1 || request.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31');
            }
            if (request.startDate == null) {
                throw new RecurringGiftException('Start date cannot be null');
            }
        }

        // Collect all contact IDs for SOQL query to get accounts
        Set<Id> contactIds = new Set<Id>();
        for (GiftRequest request : requests) {
            contactIds.add(request.contactId);
        }

        // Query contacts to get their account IDs (organization)
        Map<Id, Id> contactToAccount = new Map<Id, Id>();
        for (Contact c : [SELECT Id, AccountId FROM Contact WHERE Id IN :contactIds]) {
            contactToAccount.put(c.Id, c.AccountId);
        }

        // Prepare recurring donation records
        List<npe03__Recurring_Donation__c> recurringDonations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Contact and Organization
            rd.npe03__Contact__c = request.contactId;
            rd.npe03__Organization__c = contactToAccount.get(request.contactId);

            // Amount
            rd.npe03__Amount__c = request.amount;

            // Installment period and frequency
            rd.npe03__Installment_Period__c = 'Month';
            rd.npsp__InstallmentFrequency__c = 'Monthly';

            // Installments and open-ended status
            if (request.installments == null || request.installments == 0) {
                rd.npe03__Installments__c = null;
                rd.npe03__Open_Ended_Status__c = true;
            } else {
                rd.npe03__Installments__c = request.installments;
                rd.npe03__Open_Ended_Status__c = false;
            }

            // Schedule type and recurring type
            rd.npe03__Schedule_Type__c = 'Monthly';
            rd.npsp__RecurringType__c = 'Monthly';

            // Day of month and last day of month flag
            rd.npsp__Day_of_Month__c = request.dayOfMonth;
            rd.npsp__Always_Use_Last_Day_Of_Month__c = (request.dayOfMonth == 31);

            // Start date
            rd.npsp__StartDate__c = request.startDate;

            // End date (for fixed-length donations)
            if (request.installments != null && request.installments > 0) {
                // Calculate end date: startDate + (installments - 1) months
                Date endDate = request.startDate.addMonths(request.installments - 1);
                // If dayOfMonth is 31 and the end date doesn't have 31 days, use last day of month
                if (request.dayOfMonth == 31 && endDate.day() != 31) {
                    endDate = endDate.endOfMonth();
                }
                rd.npsp__EndDate__c = endDate;
            } else {
                rd.npsp__EndDate__c = null;
            }

            // Status and payment method
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = request.paymentMethod;

            // Date established and next payment date
            rd.npe03__Date_Established__c = request.startDate;
            rd.npe03__Next_Payment_Date__c = request.startDate;

            recurringDonations.add(rd);
        }

        // Insert recurring donations
        insert recurringDonations;

        // Return the IDs in request order
        List<Id> result = new List<Id>();
        for (npe03__Recurring_Donation__c rd : recurringDonations) {
            result.add(rd.Id);
        }
        return result;
    }
}
