public class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // Validate input map
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Map of GAU percentages cannot be null or empty');
        }

        // Validate percentages
        Decimal totalPercent = 0;
        for (Decimal percent : percentByGauId.values()) {
            if (percent == null || percent <= 0) {
                throw new AllocationException('Percentage must be greater than 0');
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total percentage cannot exceed 100%');
        }

        // Validate GAUs are active
        Set<Id> gauIds = percentByGauId.keySet();
        List<npsp__General_Accounting_Unit__c> gaus = [
            SELECT Id, npsp__Active__c 
            FROM npsp__General_Accounting_Unit__c 
            WHERE Id IN :gauIds
        ];

        for (npsp__General_Accounting_Unit__c gau : gaus) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException('GAU ' + gau.Id + ' is inactive');
            }
        }

        // Delete existing allocations for this opportunity
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id 
            FROM npsp__Allocation__c 
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // Create new allocations
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            npsp__Allocation__c allocation = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            );
            newAllocations.add(allocation);
        }

        // Insert allocations
        insert newAllocations;

        return newAllocations;
    }
}
