public class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        // Validate numberOfPayments
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be at least 1');
        }

        // Query the opportunity
        Opportunity opp = [SELECT Id, Amount, StageName FROM Opportunity WHERE Id = :opportunityId LIMIT 1];

        // Check if opportunity is closed (assuming closed stages are 'Closed Won' or 'Closed Lost')
        if (opp.StageName == 'Closed Won' || opp.StageName == 'Closed Lost') {
            throw new PaymentPlanException('Opportunity is closed');
        }

        // Query existing payments for the opportunity
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        // Calculate total paid and written-off amounts
        Decimal totalPaidAndWrittenOff = 0;
        for (npe01__OppPayment__c payment : existingPayments) {
            if (payment.npe01__Paid__c || payment.npe01__Written_Off__c) {
                totalPaidAndWrittenOff += payment.npe01__Payment_Amount__c;
            }
        }

        // Calculate outstanding amount
        Decimal outstandingAmount = opp.Amount - totalPaidAndWrittenOff;

        // Check if outstanding amount is not greater than zero
        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('Outstanding amount is not greater than zero');
        }

        // Delete existing unpaid and not written-off payments
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c payment : existingPayments) {
            if (!payment.npe01__Paid__c && !payment.npe01__Written_Off__c) {
                paymentsToDelete.add(payment);
            }
        }
        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }

        // Calculate payment amounts
        Decimal baseAmount = outstandingAmount.divide(numberOfPayments, 2, RoundingMode.DOWN);
        Decimal remainder = outstandingAmount - (baseAmount * numberOfPayments);

        // Create new payments
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c();
            payment.npe01__Opportunity__c = opportunityId;
            payment.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            payment.npe01__Payment_Date__c = null;
            payment.npe01__Paid__c = false;
            payment.npe01__Written_Off__c = false;

            // Assign amount: base amount for all except last, last gets remainder added
            if (i == numberOfPayments - 1) {
                payment.npe01__Payment_Amount__c = baseAmount + remainder;
            } else {
                payment.npe01__Payment_Amount__c = baseAmount;
            }

            newPayments.add(payment);
        }

        // Insert new payments
        insert newPayments;

        // Return in schedule order (already in order since we created sequentially)
        return newPayments;
    }
}
