public class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // Validate contact exists
        Contact contact = [SELECT Id, FirstName, LastName, AccountId FROM Contact WHERE Id = :contactId LIMIT 1];
        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist');
        }

        // Validate amount
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be positive');
        }

        // Get household account
        if (contact.AccountId == null) {
            throw new IllegalArgumentException('Contact does not have a household account');
        }
        Account householdAccount = [SELECT Id FROM Account WHERE Id = :contact.AccountId LIMIT 1];

        // Create opportunity
        Opportunity opp = new Opportunity();
        opp.Name = contact.FirstName + ' ' + contact.LastName + ' Donation ' + giftDate.format('yyyy-MM-dd');
        opp.AccountId = householdAccount.Id;
        opp.npsp__Primary_Contact__c = contact.Id;
        opp.StageName = 'Closed Won';
        insert opp;

        // Create donor contact role for primary contact
        ContactRole donorRole = new ContactRole();
        donorRole.OpportunityId = opp.Id;
        donorRole.ContactId = contact.Id;
        donorRole.Role = 'Donor';
        insert donorRole;

        // Create household member contact roles for other household members
        List<Contact> householdMembers = [SELECT Id FROM Contact WHERE AccountId = :householdAccount.Id AND Id != :contact.Id];
        for (Contact member : householdMembers) {
            ContactRole householdRole = new ContactRole();
            householdRole.OpportunityId = opp.Id;
            householdRole.ContactId = member.Id;
            householdRole.Role = 'Household Member';
            insert householdRole;
        }

        // Create payment record
        npe01__OppPayment__c payment = new npe01__OppPayment__c();
        payment.npe01__Opportunity__c = opp.Id;
        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;
        insert payment;

        return opp.Id;
    }
}
