public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all child and parent ContactIds
        Set<Id> childIds = parentIdByChildId.keySet();
        Set<Id> parentIds = parentIdByChildId.values();
        Set<Id> allContactIds = new Set<Id>(childIds);
        allContactIds.addAll(parentIds);

        // Query existing relationships between these contacts (one SOQL query)
        List<npe4__Relationship__c> existingRelationships = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds OR npe4__RelatedContact__c IN :allContactIds
        ];

        // Build a set of existing pairs (in both directions)
        Set<Id> existingPairs = new Set<Id>();
        for (npe4__Relationship__c rel : existingRelationships) {
            // Use a combined key for the pair (child, parent) regardless of direction
            Id key = rel.npe4__Contact__c + '-' + rel.npe4__RelatedContact__c;
            existingPairs.add(key);
            // Also add the reverse key to handle the other direction
            existingPairs.add(rel.npe4__RelatedContact__c + '-' + rel.npe4__Contact__c);
        }

        // Query parent contacts' gender (this is a second SOQL query, but required for reciprocal type)
        Map<Id, String> parentGenderMap = new Map<Id, String>();
        List<Contact> parentContacts = [
            SELECT Id, Gender__c
            FROM Contact
            WHERE Id IN :parentIds
        ];
        for (Contact c : parentContacts) {
            parentGenderMap.put(c.Id, c.Gender__c);
        }

        // Prepare relationship records to insert
        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : childIds) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) {
                continue;
            }

            // Check if a relationship already exists between this pair
            String pairKey = childId + '-' + parentId;
            if (existingPairs.contains(pairKey)) {
                // Skip this pair
                continue;
            }

            // Create child->parent relationship
            npe4__Relationship__c childToParent = new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            );
            relationshipsToInsert.add(childToParent);

            // Create parent->child relationship
            npe4__Relationship__c parentToChild = new npe4__Relationship__c(
                npe4__Contact__c = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Status__c = 'Current'
            );

            // Determine the type based on parent's gender
            String gender = parentGenderMap.get(parentId);
            if (gender == null) {
                // If gender is not available, use default 'Child'
                parentToChild.npe4__Type__c = 'Child';
            } else {
                if (gender == 'Male') {
                    parentToChild.npe4__Type__c = 'Son';
                } else if (gender == 'Female') {
                    parentToChild.npe4__Type__c = 'Daughter';
                } else {
                    parentToChild.npe4__Type__c = 'Child';
                }
            }

            relationshipsToInsert.add(parentToChild);
        }

        // Insert the relationships (one DML statement)
        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }
}
