public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        // Query UserRecordAccess for all record IDs in a single query
        List<UserRecordAccess> accesses = [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE RecordId IN :recordIds
              AND UserId = :UserInfo.getUserId()
        ];

        // Build a map of RecordId to edit access status
        Map<Id, Boolean> editAccessMap = new Map<Id, Boolean>();
        for (UserRecordAccess access : accesses) {
            editAccessMap.put(access.RecordId, access.HasEditAccess);
        }

        // Collect IDs where the user has edit access
        Set<Id> editableIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (editAccessMap.containsKey(recordId) && editAccessMap.get(recordId)) {
                editableIds.add(recordId);
            }
        }

        return editableIds;
    }
}
