public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // Check object-level read access
        if (!Schema.SObjectType.FB_Employee__c.getDescribe().isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Build field list for query
        List<String> fields = new List<String>();
        fields.add('Id');
        fields.add('Name');

        // Check field-level security for Department__c
        if (FB_Employee__c.Department__c.getDescribe().isReadable()) {
            fields.add('Department__c');
        }

        // Check field-level security for Salary__c
        if (FB_Employee__c.Salary__c.getDescribe().isReadable()) {
            fields.add('Salary__c');
        }

        // Check field-level security for Personal_Email__c
        if (FB_Employee__c.Personal_Email__c.getDescribe().isReadable()) {
            fields.add('Personal_Email__c');
        }

        // Construct SOQL query
        String soql = 'SELECT ' + String.join(fields, ', ') + ' FROM FB_Employee__c ORDER BY Name ASC';

        // Execute query
        return Database.query(soql);
    }
}
