public with sharing class AccountOwnershipService {
    /**
     * Reassigns ownership of Accounts and their related Contacts to a new owner.
     * Account triggers are bypassed during the Account update, then cleared.
     * Contact triggers run normally.
     *
     * @param accountIds Set of Account IDs to reassign
     * @param newOwnerId The new OwnerId for Accounts and Contacts
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Bypass all Account triggers for this transaction
        TriggerBase.bypass('Account');

        // Build list of Accounts to update
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }

        // Update Accounts with bypass in place, ensuring bypass is cleared afterward
        try {
            update accountsToUpdate;
        } finally {
            // Clear Account bypass so automation behaves normally for rest of transaction
            TriggerBase.clearBypass('Account');
        }

        // Query all Contacts related to these Accounts
        List<Contact> contactsToUpdate = [
            SELECT Id, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        // Update Contacts with new OwnerId (Contact triggers run normally)
        for (Contact c : contactsToUpdate) {
            c.OwnerId = newOwnerId;
        }
        update contactsToUpdate;
    }
}
