public class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    public void execute(FinalizerHandler.Context context) {
        Set<Id> opportunityIdsToSync = TA_Opportunity_CollectForErpSync.getOpportunityIdsToSync();

        if (!opportunityIdsToSync.isEmpty()) {
            OpportunityErpSyncJob job = new OpportunityErpSyncJob(opportunityIdsToSync);
            System.enqueueJob(job);
            // Clear the collected IDs after enqueuing to prevent duplicate jobs
            TA_Opportunity_CollectForErpSync.clearCollectedIds();
        }
    }
}
