public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        List<Lead> leads = (List<Lead>) triggerNew;
        for (Lead lead : leads) {
            // Email: leading/trailing whitespace removed and lower-cased (a null email stays null)
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }
            // Company: leading/trailing whitespace removed
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }
            // LeadSource: set to `Web` when blank; an existing value is kept
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
