public with sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        processCases(triggerNew, null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        processCases(triggerNew, triggerOld);
    }

    public void afterDelete(List<SObject> triggerOld) {
        processCases(null, triggerOld);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        processCases(triggerNew, null);
    }

    private void processCases(List<SObject> newCases, List<SObject> oldCases) {
        Set<Id> accountIds = new Set<Id>();

        if (newCases != null) {
            for (SObject sObj : newCases) {
                Case c = (Case) sObj;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        if (oldCases != null) {
            for (SObject sObj : oldCases) {
                Case c = (Case) sObj;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL Query 1: Get all cases for the affected accounts
        List<Case> allCases = [SELECT Id, AccountId, IsClosed FROM Case WHERE AccountId IN :accountIds];

        // Group by AccountId to count open cases
        Map<Id, Integer> openCaseCountMap = new Map<Id, Integer>();
        for (Case c : allCases) {
            if (!c.IsClosed) {
                openCaseCountMap.put(c.AccountId, openCaseCountMap.containsKey(c.AccountId) ? openCaseCountMap.get(c.AccountId) + 1 : 1);
            }
        }

        // Prepare Account records to update
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Account acc = new Account(Id = accountId);
            acc.FB_Open_Case_Count__c = openCaseCountMap.containsKey(accountId) ? openCaseCountMap.get(accountId) : 0;
            accountsToUpdate.add(acc);
        }

        // DML Statement 1: Update Accounts
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
